package app.awn.quran.feature.learn

import app.awn.quran.feature.learn.fsrs.FsrsCard
import app.awn.quran.feature.learn.fsrs.FsrsRating
import app.awn.quran.feature.learn.fsrs.FsrsScheduler
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner

/**
 * Replays review sequences generated by py-fsrs (`tools/generate_fsrs_vectors.py`) and requires the
 * Kotlin port to give the same due time, down to the second, after every review.
 */
@RunWith(RobolectricTestRunner::class)
class FsrsReferenceTest {

    private val vectors: JSONObject by lazy {
        val stream =
            checkNotNull(javaClass.classLoader?.getResourceAsStream("fsrs_vectors.json")) {
                "fsrs_vectors.json is missing from the test resources"
            }
        JSONObject(stream.bufferedReader(Charsets.UTF_8).use { it.readText() })
    }

    @Test
    fun allDefaultSequencesGiveTheSameDueTimeAsPyFsrs() {
        val sequences = vectors.getJSONArray("sequences")
        assertEquals(200, sequences.length())

        val scheduler = FsrsScheduler()
        val reviewCount = replay(sequences, scheduler)

        println(
            "FSRS vectors: ${sequences.length()} of ${sequences.length()} sequences, $reviewCount reviews match",
        )
    }

    @Test
    fun sequencesWithoutLearningStepsGiveTheSameDueTimeAsPyFsrs() {
        val scheduler =
            FsrsScheduler(learningStepsMillis = emptyList(), relearningStepsMillis = emptyList())

        val reviewCount = replay(vectors.getJSONArray("no_steps_sequences"), scheduler)

        assertTrue(reviewCount > 0)
    }

    @Test
    fun theVectorsRecordTheReferenceVersionAndCommit() {
        assertTrue(vectors.getString("py_fsrs_version").isNotBlank())
        assertEquals(40, vectors.getString("py_fsrs_git_commit").length)
        assertEquals(false, vectors.getBoolean("enable_fuzzing"))
    }

    /** Returns how many reviews were compared. */
    private fun replay(sequences: JSONArray, scheduler: FsrsScheduler): Int {
        var reviewCount = 0
        for (sequenceIndex in 0 until sequences.length()) {
            val sequence = sequences.getJSONObject(sequenceIndex)
            val reviews = sequence.getJSONArray("reviews")
            var card: FsrsCard? = null
            for (reviewIndex in 0 until reviews.length()) {
                val expected = reviews.getJSONObject(reviewIndex)
                val reviewMillis = expected.getLong("review_at") * MILLIS_PER_SECOND
                val before = card ?: scheduler.newCard(reviewMillis)
                val rating = FsrsRating.entries.first { it.value == expected.getInt("rating") }

                val after = scheduler.reviewCard(before, rating, reviewMillis)

                val label = "sequence ${sequence.getInt("id")} review ${reviewIndex + 1}"
                assertCardMatches(label, expected, after, reviewMillis)
                card = after
                reviewCount += 1
            }
        }
        return reviewCount
    }

    private fun assertCardMatches(
        label: String,
        expected: JSONObject,
        actual: FsrsCard,
        reviewMillis: Long,
    ) {
        assertEquals("$label due", expected.getLong("due_at") * MILLIS_PER_SECOND, actual.dueMillis)
        assertEquals(
            "$label interval in days",
            expected.getLong("interval_days"),
            (actual.dueMillis - reviewMillis) / MILLIS_PER_DAY,
        )
        assertEquals("$label state", expected.getInt("state"), actual.state.value)
        val expectedStep = if (expected.isNull("step")) 0 else expected.getInt("step")
        assertEquals("$label step", expectedStep, actual.step)
        assertEquals(
            "$label stability",
            expected.getDouble("stability"),
            checkNotNull(actual.stability),
            TOLERANCE,
        )
        assertEquals(
            "$label difficulty",
            expected.getDouble("difficulty"),
            checkNotNull(actual.difficulty),
            TOLERANCE,
        )
    }

    private companion object {
        const val MILLIS_PER_SECOND = 1_000L
        const val MILLIS_PER_DAY = 86_400_000L
        const val TOLERANCE = 1e-9
    }
}
